<script setup lang="ts">
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import { useI18n } from 'vue-i18n';
import Breadcrumbs from '../../../components/admin/Breadcrumbs.vue';
import EmptyState from '../../../components/admin/EmptyState.vue';
import PageHeader from '../../../components/admin/PageHeader.vue';
import StatusBadge from '../../../components/admin/StatusBadge.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import type { PageProps } from '../../../types';

interface PartyAddress { country_code: string; tax_id: string; legal_name: string; trade_name: string | null; address_line_1: string; address_line_2: string | null; district: string | null; province: string | null; region: string | null; postal_code: string | null; ubigeo: string | null }
interface Customer { document_type: string | null; document_number: string | null; name: string; address: string | null }
interface Totals { taxable_amount: string; exempt_amount: string; unaffected_amount: string; tax_amount: string; discount_total: string; subtotal: string; grand_total: string }
interface Item { id: string; description: string; sku: string; quantity: string; unit_price: string; base_amount: string; discount_amount: string; tax_category_code: string; tax_rate: string; taxable_amount: string | null; exempt_amount: string | null; unaffected_amount: string | null; tax_amount: string; line_total: string }
interface Submission { id: string; attempt_number: number; status: string; provider: string | null; environment: string | null; response_code: string | null; response_message: string | null; observations: string[]; signed_xml_available: boolean; cdr_available: boolean; submitted_at: string | null; responded_at: string | null }
interface CreditNote { id: string; full_number: string; status: string }
interface Document { id: string; full_number: string; document_type: string; status: string; currency: string; issue_date: string; generated_at: string; generated_by: string; order: { id: string; order_number: string }; issuer: PartyAddress; customer: Customer; totals: Totals; items: Item[]; submissions: Submission[]; credit_notes: CreditNote[] }

const props = defineProps<{ document: Document; sunat: { environment: string; can_manage: boolean } }>();
const page = usePage<PageProps>();
const { t, te, locale } = useI18n();
const submitting = ref(false);
const shown = (value: string | null) => value || t('common.notAvailable');
const typeLabel = (value: string) => te(`fiscal.types.${value}`) ? t(`fiscal.types.${value}`) : value;
const decimal = (value: string) => { const [integer, fraction = ''] = value.split('.'); return `${BigInt(integer).toLocaleString(locale.value)}${fraction ? `${locale.value.startsWith('es') ? ',' : '.'}${fraction}` : ''}`; };
const money = (value: string) => `${props.document.currency} ${decimal(value)}`;
const dateTime = (value: string | null) => value ? new Intl.DateTimeFormat(locale.value, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : t('common.notAvailable');
const address = computed(() => [props.document.issuer.district, props.document.issuer.province, props.document.issuer.region].filter(Boolean).join(', ') || t('common.notAvailable'));
const canSubmit = computed(() => props.sunat.can_manage && props.document.document_type === 'INVOICE' && ['GENERATED', 'SUBMISSION_PENDING'].includes(props.document.status));
const notice = computed(() => page.props.status ? t('fiscal.notices.submissionCompleted') : undefined);
const documentError = computed(() => {
    const value = page.props.errors?.document;
    return typeof value === 'string' ? value : undefined;
});
const submitSunat = () => {
    if (!window.confirm(t('fiscal.submitConfirm', { number: props.document.full_number }))) return;
    submitting.value = true;
    router.post(`/admin/fiscal-documents/${props.document.id}/submit-sunat`, {}, { preserveScroll: true, onFinish: () => { submitting.value = false; } });
};
</script>

<template>
    <Head :title="document.full_number" />
    <AdminLayout>
        <section class="mx-auto grid w-full max-w-[90rem] gap-5 sm:gap-6">
            <Breadcrumbs :items="[{ label: t('nav.compliance') }, { label: t('fiscal.documentsTitle'), href: '/admin/fiscal-documents' }, { label: document.full_number }]" />
            <PageHeader :title="document.full_number" :eyebrow="`${typeLabel(document.document_type)} · ${t('common.currentStore')}`" :description="t('fiscal.detailDescription')"><template #actions><StatusBadge :status="document.status" /></template></PageHeader>
            <p v-if="notice" class="rounded-md border border-admin-success-border bg-admin-success-bg p-3 text-sm font-medium text-admin-success" role="status">{{ notice }}</p>
            <p v-if="documentError" class="rounded-md border border-admin-danger-border bg-admin-danger-bg p-3 text-sm font-medium text-admin-danger" role="alert">{{ documentError }}</p>

            <div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                <article class="admin-card p-4"><p class="admin-label">{{ t('fiscal.issueDate') }}</p><p class="mt-2 font-mono text-base font-semibold">{{ document.issue_date }}</p></article>
                <article class="admin-card p-4"><p class="admin-label">{{ t('fiscal.generatedAt') }}</p><p class="mt-2 text-sm font-semibold">{{ dateTime(document.generated_at) }}</p><p class="mt-1 text-xs text-admin-neutral">{{ t('fiscal.generatedBy', { name: document.generated_by }) }}</p></article>
                <article class="admin-card p-4"><p class="admin-label">{{ t('fiscal.order') }}</p><Link :href="`/admin/orders/${document.order.id}`" class="mt-2 block font-mono text-base font-semibold text-admin-secondary hover:underline">{{ document.order.order_number }}</Link></article>
                <article class="admin-card border-admin-primary bg-admin-primary p-4 text-white"><p class="admin-label text-slate-300">{{ t('fiscal.grandTotal') }}</p><p class="mt-2 font-mono text-xl font-semibold tabular-nums">{{ money(document.totals.grand_total) }}</p></article>
            </div>

            <div class="grid gap-4 lg:grid-cols-2">
                <section class="admin-card p-4 sm:p-5"><p class="admin-label text-admin-secondary">{{ t('fiscal.issuerSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('fiscal.issuer') }}</h2><dl class="mt-4 grid gap-x-5 gap-y-4 sm:grid-cols-2"><div><dt class="admin-label">{{ t('fiscal.legalName') }}</dt><dd class="mt-1 break-words font-semibold">{{ document.issuer.legal_name }}</dd></div><div><dt class="admin-label">{{ t('fiscal.tradeName') }}</dt><dd class="mt-1 break-words">{{ shown(document.issuer.trade_name) }}</dd></div><div><dt class="admin-label">{{ t('fiscal.taxId') }}</dt><dd class="mt-1 font-mono">{{ document.issuer.country_code }} · {{ document.issuer.tax_id }}</dd></div><div><dt class="admin-label">{{ t('fiscal.ubigeoAndPostal') }}</dt><dd class="mt-1 font-mono">{{ shown(document.issuer.ubigeo) }} · {{ shown(document.issuer.postal_code) }}</dd></div><div class="sm:col-span-2"><dt class="admin-label">{{ t('fiscal.fiscalAddress') }}</dt><dd class="mt-1 break-words">{{ document.issuer.address_line_1 }}<template v-if="document.issuer.address_line_2">, {{ document.issuer.address_line_2 }}</template><br>{{ address }}</dd></div></dl></section>
                <section class="admin-card p-4 sm:p-5"><p class="admin-label text-admin-secondary">{{ t('fiscal.customerSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('fiscal.customerSnapshot') }}</h2><dl class="mt-4 grid gap-x-5 gap-y-4 sm:grid-cols-2"><div class="sm:col-span-2"><dt class="admin-label">{{ t('fiscal.name') }}</dt><dd class="mt-1 break-words font-semibold">{{ document.customer.name }}</dd></div><div><dt class="admin-label">{{ t('fiscal.customerDocumentType') }}</dt><dd class="mt-1 font-mono">{{ shown(document.customer.document_type) }}</dd></div><div><dt class="admin-label">{{ t('fiscal.customerDocumentNumber') }}</dt><dd class="mt-1 break-all font-mono">{{ shown(document.customer.document_number) }}</dd></div><div class="sm:col-span-2"><dt class="admin-label">{{ t('fiscal.address') }}</dt><dd class="mt-1 break-words">{{ shown(document.customer.address) }}</dd></div></dl></section>
            </div>

            <section class="grid gap-3" aria-labelledby="fiscal-items-heading"><div><p class="admin-label text-admin-secondary">{{ t('fiscal.itemsSection') }}</p><h2 id="fiscal-items-heading" class="mt-1 text-lg font-semibold">{{ t('fiscal.items') }}</h2><p class="mt-1 text-sm text-admin-neutral">{{ t('fiscal.itemsHelp') }}</p></div>
                <div class="admin-card hidden overflow-hidden lg:block"><table class="admin-table w-full table-fixed text-left text-xs"><thead><tr><th class="w-[23%] p-3">{{ t('fiscal.item') }}</th><th class="w-[8%] p-3 text-right">{{ t('fiscal.quantity') }}</th><th class="w-[12%] p-3 text-right">{{ t('fiscal.unitPrice') }}</th><th class="w-[11%] p-3 text-right">{{ t('fiscal.base') }}</th><th class="w-[11%] p-3 text-right">{{ t('fiscal.discount') }}</th><th class="w-[13%] p-3">{{ t('fiscal.categoryAndRate') }}</th><th class="w-[10%] p-3 text-right">{{ t('fiscal.tax') }}</th><th class="w-[12%] p-3 text-right">{{ t('fiscal.lineTotal') }}</th></tr></thead><tbody class="divide-y divide-admin-border"><tr v-for="item in document.items" :key="item.id"><td class="p-3"><p class="font-medium">{{ item.description }}</p><p class="mt-1 font-mono text-[11px] text-admin-neutral">{{ item.sku }}</p></td><td class="p-3 text-right font-mono tabular-nums">{{ decimal(item.quantity) }}</td><td class="p-3 text-right font-mono tabular-nums">{{ money(item.unit_price) }}</td><td class="p-3 text-right font-mono tabular-nums">{{ money(item.base_amount) }}</td><td class="p-3 text-right font-mono tabular-nums">{{ money(item.discount_amount) }}</td><td class="p-3"><p class="font-mono font-medium">{{ item.tax_category_code }}</p><p class="text-admin-neutral">{{ decimal(item.tax_rate) }}%</p></td><td class="p-3 text-right font-mono tabular-nums">{{ money(item.tax_amount) }}</td><td class="p-3 text-right font-mono font-semibold tabular-nums">{{ money(item.line_total) }}</td></tr></tbody></table></div>
                <div class="grid gap-3 lg:hidden"><article v-for="item in document.items" :key="`mobile-${item.id}`" class="admin-card min-w-0 p-4"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><p class="break-words font-semibold">{{ item.description }}</p><p class="mt-1 break-all font-mono text-xs text-admin-neutral">{{ item.sku }}</p></div><p class="shrink-0 font-mono text-xs">× {{ decimal(item.quantity) }}</p></div><dl class="mt-4 grid grid-cols-2 gap-3 text-xs"><div><dt class="admin-label">{{ t('fiscal.unitPrice') }}</dt><dd class="mt-1 font-mono">{{ money(item.unit_price) }}</dd></div><div><dt class="admin-label">{{ t('fiscal.base') }}</dt><dd class="mt-1 font-mono">{{ money(item.base_amount) }}</dd></div><div><dt class="admin-label">{{ t('fiscal.discount') }}</dt><dd class="mt-1 font-mono">{{ money(item.discount_amount) }}</dd></div><div><dt class="admin-label">{{ t('fiscal.tax') }}</dt><dd class="mt-1 font-mono">{{ money(item.tax_amount) }}</dd></div><div><dt class="admin-label">{{ t('fiscal.categoryAndRate') }}</dt><dd class="mt-1 font-mono">{{ item.tax_category_code }} · {{ decimal(item.tax_rate) }}%</dd></div><div><dt class="admin-label">{{ t('fiscal.lineTotal') }}</dt><dd class="mt-1 font-mono font-semibold">{{ money(item.line_total) }}</dd></div></dl></article></div>
            </section>

            <section class="rounded-lg bg-admin-primary p-4 text-white sm:p-5"><p class="admin-label text-slate-300">{{ t('fiscal.totalsSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('fiscal.exactTotals') }}</h2><dl class="mt-4 grid grid-cols-2 gap-3 lg:grid-cols-4"><div v-for="row in [[t('fiscal.taxableBase'), document.totals.taxable_amount], [t('fiscal.exemptBase'), document.totals.exempt_amount], [t('fiscal.unaffectedBase'), document.totals.unaffected_amount], [t('fiscal.discount'), document.totals.discount_total], [t('fiscal.subtotal'), document.totals.subtotal], [t('fiscal.taxAmount'), document.totals.tax_amount], [t('fiscal.grandTotal'), document.totals.grand_total]]" :key="row[0]" class="rounded-md border border-white/20 p-3" :class="row[0] === t('fiscal.grandTotal') ? 'col-span-2 bg-white text-admin-primary lg:col-span-1' : ''"><dt class="admin-label opacity-75">{{ row[0] }}</dt><dd class="mt-2 font-mono text-sm font-semibold tabular-nums sm:text-base">{{ money(row[1]) }}</dd></div></dl></section>

            <section class="rounded-lg border border-admin-warning-border bg-admin-warning-bg p-4 sm:p-5"><div class="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><p class="admin-label text-amber-700">SUNAT · {{ sunat.environment }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('fiscal.transmission') }}</h2><p class="mt-1 max-w-3xl text-sm text-admin-text-secondary">{{ sunat.environment === 'BETA' ? t('fiscal.betaWarning') : t('fiscal.environmentWarning') }}</p></div><button v-if="canSubmit" type="button" :disabled="submitting" class="min-h-10 shrink-0 rounded-md bg-admin-primary px-4 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-50" @click="submitSunat">{{ submitting ? t('fiscal.submitting') : t('fiscal.submitInvoice') }}</button></div><p v-if="document.document_type === 'RECEIPT'" class="mt-4 rounded-md border border-admin-border bg-white p-3 text-xs text-admin-text-secondary">{{ t('fiscal.receiptBlocked') }}</p><p v-else-if="['SUBMITTED', 'ACCEPTED', 'REJECTED'].includes(document.status)" class="mt-4 rounded-md border border-admin-border bg-white p-3 text-xs text-admin-text-secondary">{{ t('fiscal.resubmitBlocked') }}</p><p v-else-if="!sunat.can_manage" class="mt-4 text-xs text-admin-text-secondary">{{ t('fiscal.manageRequired') }}</p></section>

            <div class="grid gap-4 lg:grid-cols-2">
                <section class="grid content-start gap-3"><div><p class="admin-label text-admin-secondary">{{ t('fiscal.submissionsSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('fiscal.submissionHistory') }}</h2><p class="mt-1 text-sm text-admin-neutral">{{ t('fiscal.submissionHelp') }}</p></div><div v-if="document.submissions.length" class="grid gap-3"><article v-for="submission in document.submissions" :key="submission.id" class="admin-card min-w-0 p-4"><div class="flex items-start justify-between gap-3"><div><p class="font-mono text-sm font-semibold">{{ t('fiscal.attempt', { number: submission.attempt_number }) }}</p><p class="mt-1 text-xs text-admin-neutral">{{ shown(submission.provider) }} · {{ shown(submission.environment) }}</p></div><StatusBadge :status="submission.status" /></div><dl class="mt-4 grid gap-3 text-xs sm:grid-cols-2"><div><dt class="admin-label">{{ t('fiscal.responseCode') }}</dt><dd class="mt-1 break-all font-mono">{{ shown(submission.response_code) }}</dd></div><div><dt class="admin-label">{{ t('fiscal.responseMessage') }}</dt><dd class="mt-1 break-words">{{ shown(submission.response_message) }}</dd></div><div><dt class="admin-label">{{ t('fiscal.submittedAt') }}</dt><dd class="mt-1">{{ dateTime(submission.submitted_at) }}</dd></div><div><dt class="admin-label">{{ t('fiscal.respondedAt') }}</dt><dd class="mt-1">{{ dateTime(submission.responded_at) }}</dd></div></dl><div v-if="submission.observations.length" class="mt-4 border-t border-admin-border pt-3"><p class="admin-label">{{ t('fiscal.observations') }}</p><ul class="mt-2 list-disc space-y-1 pl-5 text-xs"><li v-for="observation in submission.observations" :key="observation" class="break-words">{{ observation }}</li></ul></div><div v-if="sunat.can_manage && (submission.signed_xml_available || submission.cdr_available)" class="mt-4 flex flex-col gap-2 border-t border-admin-border pt-3 sm:flex-row"><a v-if="submission.signed_xml_available" :href="`/admin/fiscal-documents/${document.id}/submissions/${submission.id}/artifacts/signed-xml`" class="inline-flex min-h-9 items-center justify-center rounded-md border border-admin-border-strong bg-white px-3 text-xs font-semibold">{{ t('fiscal.downloadSignedXml') }}</a><a v-if="submission.cdr_available" :href="`/admin/fiscal-documents/${document.id}/submissions/${submission.id}/artifacts/cdr`" class="inline-flex min-h-9 items-center justify-center rounded-md border border-admin-border-strong bg-white px-3 text-xs font-semibold">{{ t('fiscal.downloadCdr') }}</a></div></article></div><EmptyState v-else :title="t('fiscal.noSubmissions')" :description="t('fiscal.noSubmissionsHelp')" /></section>
                <section class="grid content-start gap-3"><div><p class="admin-label text-admin-secondary">{{ t('fiscal.relatedSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('fiscal.creditNotes') }}</h2><p class="mt-1 text-sm text-admin-neutral">{{ t('fiscal.creditNotesHelp') }}</p></div><div v-if="document.credit_notes.length" class="grid gap-3"><Link v-for="note in document.credit_notes" :key="note.id" :href="`/admin/fiscal-documents/${note.id}`" class="admin-card flex min-w-0 items-center justify-between gap-3 p-4"><span class="break-all font-mono text-sm font-semibold text-admin-secondary">{{ note.full_number }}</span><StatusBadge :status="note.status" /></Link></div><EmptyState v-else :title="t('fiscal.noCreditNotes')" :description="t('fiscal.noCreditNotesHelp')" /></section>
            </div>
        </section>
    </AdminLayout>
</template>
